CREATE DATABASE IF NOT EXISTS secure_drive CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE secure_drive;
CREATE TABLE roles (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL UNIQUE,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT IGNORE INTO roles(name,description) VALUES ('admin','System administrator'),('user','Regular user');
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role_id INT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE files (id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,filename VARCHAR(255) NOT NULL,content_type VARCHAR(150),size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,current_version_id BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,FOREIGN KEY(owner_id) REFERENCES users(id),INDEX(owner_id)) ENGINE=InnoDB;
CREATE TABLE file_versions (id BIGINT AUTO_INCREMENT PRIMARY KEY,file_id BIGINT NOT NULL,version_number INT NOT NULL,object_key VARCHAR(512) NOT NULL UNIQUE,size_bytes BIGINT UNSIGNED NOT NULL,checksum_sha256 CHAR(64),uploaded_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(file_id) REFERENCES files(id),FOREIGN KEY(uploaded_by) REFERENCES users(id),UNIQUE(file_id,version_number)) ENGINE=InnoDB;
ALTER TABLE files ADD CONSTRAINT fk_files_current_version FOREIGN KEY(current_version_id) REFERENCES file_versions(id) ON DELETE SET NULL;
CREATE TABLE file_permissions (id BIGINT AUTO_INCREMENT PRIMARY KEY,file_id BIGINT NOT NULL,user_id INT NOT NULL,permission ENUM('read','write') NOT NULL,granted_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(file_id) REFERENCES files(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(granted_by) REFERENCES users(id),UNIQUE(file_id,user_id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100) NOT NULL,file_id BIGINT NULL,status ENUM('success','denied','failure') NOT NULL,ip_address VARCHAR(45),details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(file_id) REFERENCES files(id) ON DELETE SET NULL,INDEX(created_at),INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY,email_attempted VARCHAR(255) NOT NULL,ip_address VARCHAR(45),was_successful BOOLEAN NOT NULL DEFAULT FALSE,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(email_attempted,attempted_at)) ENGINE=InnoDB;
SHOW TABLES;
